    ph_name: "Jeanne Dupont", ph_email: "jeanne@entreprise.com", ph_budget: "5k – 10k €", ph_message: "Parlez-moi de votre projet...",
    btn_send: "Envoyer le Message →", btn_sending: "Envoi...", btn_sent: "Message envoyé ✓",
